const ozSocialscience6Zor = <(String, String, List<String>, String)>[
  ('Emile Durkheim\'ın Latince yazdığı ikinci doktora tezi, siyaset biliminin kuruluşuna katkıları bakımından hangi düşünürü konu alır?', 'Montesquieu', ['Rousseau', 'Voltaire', 'Saint-Simon'], 'Durkheim 1892\'de Montesquieu\'nün toplum bilimine katkısını inceleyen Latince bir tez yazdı. Bu tez Durkheim\'ın Montesquieu\'yü sosyolojinin öncüsü saydığını gösterir.'),
  ('Comte\'un kendi bilimine "sosyal fizik" yerine yeni bir ad olan "sosyoloji"yi vermesinde, eski terimin hangi düşünür tarafından da istatistik çalışmaları için kullanılması etkili olmuştur?', 'Adolphe Quetelet', ['John Stuart Mill', 'Herbert Spencer', 'Frédéric Le Play'], 'Quetelet istatistiğe dayalı çalışmalarına "sosyal fizik" adını verince Comte, kendi görüşünü ondan ayırmak için "sosyoloji" terimini önerdi.'),
  ('Tocqueville\'in Fransız Devrimi\'nin aslında Eski Rejim döneminde başlamış merkezîleşme eğilimini sürdürdüğünü ileri sürdüğü eseri hangisidir?', 'Eski Rejim ve Devrim', ['Toplum Sözleşmesi', 'Fransa\'da Sınıf Mücadeleleri', 'Devrim Üzerine Düşünceler'], 'Tocqueville 1856\'da yayımlanan "Eski Rejim ve Devrim"de, devrimin kopuştan çok önceki dönemin merkezîleşmesinin devamı olduğunu savundu.'),
  ('Bugün "başkalarının iyiliğini gözetme" anlamında kullanılan "altruizm" (özgecilik) terimini türeten düşünür kimdir?', 'Auguste Comte', ['Emile Durkheim', 'Adam Smith', 'Herbert Spencer'], 'Altruizm terimini Comte, egoizmin karşıtı olarak türetti. Durkheim bu sözcüğü daha sonra intihar türlerinden birini adlandırırken kullandı.'),
  ('Harriet Martineau\'nun "Ahlak ve Görgüler Nasıl Gözlemlenir" (1838) adlı eserinin sosyoloji tarihindeki önemi hangisidir?', 'Toplumsal araştırma yöntemine ayrılmış ilk sistemli eserlerden olması', ['Sosyoloji teriminin ilk kez bu eserde kullanılması', 'İlk kentsel istatistik yıllığı olması', 'Kadınlara oy hakkı tanıyan İngiliz yasasının ilk taslağını içermesi'], 'Martineau bu eserinde bir toplumu gözlemlerken izlenecek ilkeleri ve gözlemcinin yanlılıklarından nasıl kaçınacağını tartıştı. Eser, sosyal araştırma yöntemi üzerine ilk çalışmalardan sayılır.'),
  ('Spencer evrimi üç düzeyde ele alır. Bunlardan toplumların ve kültürün evrimini kapsayan düzeye verdiği ad hangisidir?', 'Üstorganik evrim', ['İnorganik evrim', 'Organik evrim', 'Ruhsal evrim'], 'Spencer evrimi inorganik (cansız doğa), organik (canlılar) ve üstorganik (toplum ve kültür) düzeylerde inceledi. Sosyoloji üstorganik evrimle ilgilenir.'),
  ('Durkheim\'ın 1898\'de kurduğu ve çevresinde Mauss, Halbwachs gibi araştırmacıların toplandığı süreli yayın hangisidir?', 'L\'Année sociologique', ['American Journal of Sociology', 'Revue des Deux Mondes', 'Zeitschrift für Sozialforschung'], 'L\'Année sociologique Durkheim okulunun yayın organıydı. American Journal of Sociology Chicago\'da, Zeitschrift für Sozialforschung Frankfurt Okulu çevresinde çıkarıldı.'),
  ('Durkheim\'ın, bir topluluğun dünyayı algılama biçimini belirleyen ve kuşaktan kuşağa aktarılan ortak kavramlar, simgeler ve düşünceler için kullandığı kavram hangisidir?', 'Kolektif tasavvurlar', ['Bireysel izlenimler', 'Üretim ilişkileri', 'İdeal tipler'], 'Kolektif tasavvurlar, bireylerin tek tek ürettiği değil, toplumsal yaşamdan doğan ortak düşünce ve simgelerdir. Zaman, mekân ve sınıflandırma kategorileri de bunlardandır.'),
  ('Durkheim, modern toplumlarda ekonomik yaşamdaki anomiyi azaltmak için "Toplumsal İşbölümü Üzerine" eserinin ikinci baskı önsözünde hangi yapıların güçlendirilmesini önermiştir?', 'Meslek gruplarının', ['Askerî örgütlerin', 'Geniş ailenin', 'Gizli tarikatların'], 'Durkheim, devlet ile birey arasında ahlaki kurallar üretecek ara kurumlar olarak meslek gruplarının yeniden canlandırılmasını önerdi.'),
  ('Weber "kapitalizmin ruhu"nu örneklemek için "Zaman paradır" gibi öğütlerini aktardığı hangi kişinin yazılarından yararlanmıştır?', 'Benjamin Franklin', ['Adam Smith', 'Martin Luther', 'John Calvin'], 'Weber, Benjamin Franklin\'in tutumluluğu, dakikliği ve kazancı bir ödev olarak gören öğütlerini kapitalizmin ruhunun saf bir örneği olarak aktarır.'),
  ('Weber\'in Luther\'in İncil çevirisine kadar izini sürdüğü, işi Tanrı\'nın verdiği bir görev olarak anlamlandıran kavram hangisidir?', 'Meslek ya da çağrı (Beruf)', ['Lütuf (karizma)', 'Kast (varna)', 'Lonca (zünft)'], 'Almanca Beruf hem meslek hem de ilahi çağrı anlamı taşır. Weber, Protestanlıkla birlikte gündelik mesleki çalışmanın dinsel bir değer kazandığını savunur.'),
  ('Bir ülkede yöneticinin devleti kendi kişisel mülkü ve hanesi gibi yönettiği, görevlilerin de ona kişisel sadakatle bağlı hizmetkârlar olduğu yönetim biçimi Weber\'e göre hangi kavramla adlandırılır?', 'Patrimonyalizm', ['Bürokrasi', 'Gerontokrasi', 'Teknokrasi'], 'Patrimonyalizm, geleneksel otoritenin bir alt türüdür. Yönetici kamusal işleri kişisel hanesinin uzantısı gibi yürütür; görevliler yasaya değil yöneticiye bağlıdır.'),
  ('Weber\'in sınıf kavramında bireyin piyasa durumuna bağlı olarak mal, gelir ve iyi yaşam koşullarına erişme olasılığını anlatan kavram hangisidir?', 'Yaşam şansları', ['Artı değer', 'Kültürel sermaye', 'Kolektif bilinç'], 'Weber sınıfı, piyasadaki ortak konumun belirlediği benzer yaşam şanslarına sahip insanlar olarak tanımlar.'),
  ('Bir grubun kaynaklara ve ayrıcalıklara erişimi belirli ölçütlerle sınırlayarak dışarıdakileri dışlamasını anlatan ve Weber\'den türetilen kavram hangisidir?', 'Toplumsal kapanma', ['Toplumsal hareketlilik', 'Kültürleşme', 'Kolektif coşku'], 'Weber\'e göre gruplar diploma, soy, din ya da etnik köken gibi ölçütlerle üyeliği sınırlayarak ayrıcalıklarını korur; bu sürece toplumsal kapanma denir.'),
  ('Weber\'e göre Hindistan\'daki kast sistemi kendi kavramlarıyla en iyi nasıl nitelendirilir?', 'Dinsel olarak meşrulaştırılmış kapalı statü grupları', ['Piyasa durumuna dayalı açık sınıflar', 'Karizmatik liderlerin çevresinde kurulan siyasal partiler', 'Rasyonel bürokratik örgütler'], 'Weber "Hindistan\'ın Dini" çalışmasında kastları, evlilik ve sofra kurallarıyla birbirinden ayrılan, dinsel olarak kutsanmış ve kapalı statü grupları olarak inceler.'),
  ('Weber\'in, yargıcın genel kurallara değil, her olayın kendi özelliklerine ve kişisel hakkaniyet anlayışına göre karar verdiği yargılama tarzını adlandırmak için kullandığı ideal tip hangisidir?', 'Kadı adaleti', ['Biçimsel-rasyonel hukuk', 'Doğal hukuk', 'Pozitif hukuk'], 'Weber "kadı adaleti" (Kadijustiz) terimini öngörülebilir genel kurallara dayanmayan, olay bazlı yargılama için ideal tip olarak kullandı. Bu kavram onun tarihsel kaynaklarına ilişkin eleştirilere de konu olmuştur.'),
  ('Weber\'in fikirler ile çıkarlar arasındaki ilişkiyi anlatmak için Goethe\'den ödünç aldığı, Protestan ahlakı ile kapitalizmin ruhu arasındaki uyumu açıklayan kavram hangisidir?', 'Seçici yakınlık', ['Diyalektik çelişki', 'Kolektif temsil', 'İşlevsel gereklilik'], 'Seçici yakınlık (Wahlverwandtschaft), iki ayrı olgunun birbirini doğrudan üretmeden karşılıklı olarak destekleyip birbirine çekilmesini anlatır.'),
  ('Engels\'in, Lewis Henry Morgan\'ın antropolojik çalışmalarından yararlanarak aile ve devletin tarihsel gelişimini özel mülkiyetin ortaya çıkışıyla ilişkilendirdiği eseri hangisidir?', 'Ailenin, Özel Mülkiyetin ve Devletin Kökeni', ['Anti-Dühring', 'Konut Sorunu', 'Köylü Savaşı'], 'Engels 1884 tarihli bu eserde, özel mülkiyetin ve mirasın ortaya çıkmasıyla tek eşli ataerkil ailenin ve sınıflı toplumu koruyan devletin doğduğunu savundu.'),
  ('Marx\'ın yabancılaşma kavramını ayrıntılı biçimde işlediği, ancak ölümünden çok sonra, 1932\'de yayımlanan gençlik dönemi metni hangisidir?', '1844 Ekonomik ve Felsefi El Yazmaları', ['Kapital\'in birinci cildi', 'Fransa\'da İç Savaş', 'Felsefenin Sefaleti'], '1844 El Yazmaları Marx\'ın genç dönem düşüncesini yansıtır ve 20. yüzyılda yayımlanınca yabancılaşma kavramına ilginin artmasına yol açmıştır.'),
  ('Marx\'ın ayrımına göre, aynı üretim ilişkisi içinde bulunan ama ortak çıkarlarının henüz farkına varmamış ve örgütlenmemiş işçiler hangi kavramla nitelenir?', 'Kendinde sınıf', ['Kendisi için sınıf', 'Statü grubu', 'Lümpenproletarya'], 'Marx nesnel olarak aynı konumdaki grubu "kendinde sınıf", bilinçlenip çıkarları için örgütlenen sınıfı ise "kendisi için sınıf" olarak ayırır.'),
  ('Marx\'ın, Batı Avrupa\'nınkinden farklı olarak toprakta özel mülkiyetin gelişmediği ve sulama işlerini yöneten güçlü bir merkezî devletin bulunduğu toplumlar için kullandığı kavram hangisidir?', 'Asya tipi üretim tarzı', ['Feodal üretim tarzı', 'Köleci üretim tarzı', 'Kapitalist üretim tarzı'], 'Marx Hindistan ve Çin gibi toplumlar için Asya tipi üretim tarzı kavramını kullandı; bu toplumlarda köy toplulukları ile merkezî devlet arasında bir ilişki öne çıkar.'),
  ('Marx\'ın "Louis Bonaparte\'ın On Sekiz Brumaire\'i" adlı eserinde Fransız küçük köylülerini "bir çuval patates"e benzetmesinin nedeni hangisidir?', 'Benzer konumda olmalarına karşın aralarında bağ ve örgütlenme bulunmaması', ['Yalnızca patates tarımıyla geçinmeleri', 'Devrimin öncü sınıfı olmaları', 'Kentlerdeki sanayi işçileriyle her zaman sıkı bir siyasal ittifak kurmuş olmaları'], 'Marx\'a göre köylüler birbirinden yalıtılmış küçük işletmelerde yaşadıkları için bir sınıf gibi örgütlenemez; birbirine eklenmiş tek tek parçalar gibidirler.'),
  ('Marx\'ın aynı eserinde Hegel\'e gönderme yaparak tarihsel olayların tekrarı hakkında söylediği söz hangisidir?', 'Önce trajedi, sonra komedi (fars) olarak', ['Önce komedi, sonra trajedi olarak', 'Her seferinde aynı biçimde', 'Hiçbir zaman tekrarlanmayarak'], 'Marx, Hegel\'in büyük olayların iki kez yaşandığı sözüne ekleme yaparak birincisinin trajedi, ikincisinin fars olarak yaşandığını söyler ve III. Napolyon\'u buna örnek gösterir.'),
  ('Simmel\'in üç kişilik grup çözümlemesinde, diğer iki üye arasındaki anlaşmazlıktan kendi çıkarı için yararlanan üçüncü kişiye verdiği ad hangisidir?', 'Gülen üçüncü', ['Genelleştirilmiş öteki', 'Kapı bekçisi', 'Marjinal insan'], 'Simmel üçlü grupta üçüncü kişinin arabulucu, "böl ve yönet" yapan ya da iki tarafın çekişmesinden kazanç sağlayan "gülen üçüncü" rollerini üstlenebileceğini gösterir.'),
  ('Simmel\'in, insanların herhangi bir çıkar gözetmeden yalnızca bir arada olmanın keyfi için kurdukları sohbet ve toplantılara özgü saf etkileşim biçimine verdiği ad hangisidir?', 'Sosyallik', ['Rasyonelleşme', 'Yabancılaşma', 'Toplumsal olgu'], 'Simmel sosyalliği, içeriksiz ve amaçsız, salt etkileşimin oyun biçimi olarak tanımlar. Kibar sohbet ve davetler buna örnektir.'),
  ('Tönnies\'in "Cemaat ve Cemiyet" adlı eseri hangi yılda yayımlanmıştır?', '1887', ['1848', '1912', '1930'], 'Tönnies\'in Gemeinschaft und Gesellschaft adlı eseri 1887\'de yayımlandı ve geleneksel-modern toplum karşıtlığını işleyen ilk sistemli çalışmalardan biri oldu.'),
  ('Tönnies\'e göre cemaatin üç temel biçimi hangi bağlara dayanır?', 'Kan, yer ve zihin (ruh) birliği', ['Sınıf, statü ve parti', 'Sözleşme, piyasa ve devlet', 'Dil, para ve hukuk'], 'Tönnies cemaatin akrabalıkta kan birliği, komşulukta yer birliği, dostlukta ise zihin birliği biçiminde görüldüğünü belirtir.'),
  ('Pareto\'nun insan davranışlarının büyük bölümünü açıklarken kullandığı "tortular" ve "türevler" kavramları hangi eylem türüyle ilgilidir?', 'Mantıksal olmayan eylemlerle', ['Amaçsal-rasyonel ekonomik eylemlerle', 'Bilimsel deneylerle', 'Hukuki sözleşmelerle'], 'Pareto\'ya göre insanlar çoğunlukla duygusal kaynaklı tortulara göre davranır, ardından bu davranışları akla yatkın görünen gerekçelerle, yani türevlerle meşrulaştırır.'),
  ('Gaetano Mosca\'ya göre yönetici sınıfın iktidarını din, ulus ya da halk egemenliği gibi genel kabul gören bir ilkeye dayandırarak meşrulaştırmasına ne ad verilir?', 'Siyasal formül', ['Toplumsal sözleşme', 'Sınıf bilinci', 'Kolektif coşku'], 'Mosca, her yönetici sınıfın iktidarını çıplak güçle değil, toplumun inandığı bir ilkeye bağlayan bir siyasal formülle haklı gösterdiğini savunur.'),
  ('Robert Michels "oligarşinin tunç yasası"na ulaşırken özellikle hangi tür örgütü incelemiştir?', 'Alman Sosyal Demokrat Partisi gibi demokratik işçi partilerini', ['Katolik Kilisesi\'nin manastırlarını', 'Prusya ordusunun subay kadrosunu', 'Büyük ticaret şirketlerinin yönetim kurullarını ve hissedar toplantılarını'], 'Michels\'in çarpıcı sonucu, demokrasiyi savunan sosyalist partilerin bile örgütlenme gereği nedeniyle küçük bir yönetici kadronun denetimine girmesiydi.'),
  ('Frédéric Le Play\'in işçi ailelerini incelerken temel veri kaynağı olarak kullandığı ve gelir-gider kalemlerini ayrıntılı kaydettiği araç hangisidir?', 'Aile bütçeleri', ['Nüfus sayımı sonuçları', 'Mahkeme kayıtları', 'Gazete haberleri'], 'Le Play "Avrupalı İşçiler" adlı eserinde ailelerin bütçelerini ayrıntılı biçimde çıkararak yaşam koşullarını inceledi; bu yöntem monografi geleneğinin temelini oluşturdu.'),
  ('Le Play\'in aile tipolojisinde, mirasın tek bir çocuğa geçtiği, diğer çocukların evden ayrılıp başka yerlerde iş kurduğu ve böylece hem geleneğin hem girişimciliğin korunduğu aile tipi hangisidir?', 'Kök aile', ['Ataerkil aile', 'İstikrarsız aile', 'Çekirdek aile'], 'Le Play kök aileyi (famille souche) en sağlıklı tip sayar: bir mirasçı ocağı sürdürür, diğerleri kendi girişimleriyle yaşamlarını kurar.'),
  ('Gabriel Tarde\'ın, gazetelerin yaygınlaşmasıyla birlikte fiziksel olarak bir arada bulunmadan aynı düşünceleri paylaşan insanlar için kullandığı kavram hangisidir?', 'Kamu', ['Kalabalık', 'Klan', 'Kast'], 'Tarde kalabalığı fiziksel yakınlığa, kamuyu ise basın aracılığıyla oluşan zihinsel birlikteliğe dayandırır ve modern çağı "kamular çağı" olarak niteler.'),
  ('Mukaddime\'nin Osmanlı Türkçesine çevrilmesinde ilk bölümleri Pîrîzâde Mehmed Sâhib\'in çevirmesinden sonra çeviriyi tamamlayan devlet adamı kimdir?', 'Ahmed Cevdet Paşa', ['Kâtip Çelebi', 'Namık Kemal', 'Mustafa Reşid Paşa'], 'Pîrîzâde 18. yüzyılda Mukaddime\'nin büyük bölümünü çevirdi; kalan altıncı bölümü 19. yüzyılda Ahmed Cevdet Paşa Türkçeye kazandırdı.'),
  ('Ziya Gökalp\'in toplumu harekete geçiren ve bireyleri ortak bir amaç için fedakârlığa yönelten kolektif ülküyü adlandırmak için kullandığı kavram hangisidir?', 'Mefkûre', ['Asabiyet', 'Hars', 'Medeniyet'], 'Gökalp\'e göre mefkûre, toplumun büyük bunalım anlarında ortaya çıkan ve bireyleri ortak ülküye bağlayan kolektif idealdir.'),
  ('1917\'de Ziya Gökalp\'in yönetiminde İstanbul Darülfünunu\'na bağlı çalışma kurulunca çıkarılan ve Türkiye\'deki ilk sosyoloji dergisi sayılan yayın hangisidir?', 'İçtimaiyat Mecmuası', ['Servet-i Fünun', 'Yeni Mecmua', 'Genç Kalemler'], 'İçtimaiyat Mecmuası, Darülfünun bünyesindeki İçtimaiyat Darülmesaisi tarafından yayımlandı. Genç Kalemler ve Yeni Mecmua da Gökalp\'le ilişkili olsa da sosyoloji dergisi değildir.'),
  ('Ziya Gökalp\'in 1922-1923\'te memleketi Diyarbakır\'da çıkardığı dergi hangisidir?', 'Küçük Mecmua', ['Türk Yurdu', 'Halka Doğru', 'Ülkü'], 'Gökalp Malta sürgününden dönünce Diyarbakır\'da Küçük Mecmua\'yı çıkardı ve millî mücadeleyi destekleyen yazılar yayımladı.'),
  ('Prens Sabahattin\'in görüşlerini biçimlendiren ve "Anglosaksonların üstünlüğü neye dayanır?" sorusunu soran eseriyle tanınan Fransız düşünür kimdir?', 'Edmond Demolins', ['Emile Durkheim', 'Gabriel Tarde', 'Gustave Le Bon'], 'Demolins, Le Play\'in izinden giden İlm-i İçtima (Science sociale) okulunun temsilcisiydi. Anglosaksonların başarısını bireyci aile ve eğitim yapısına bağladı.'),
  ('Niyazi Berkes, Behice Boran ve Pertev Naili Boratav\'ın ortak bir yaşam deneyimi hangisidir?', '1948\'de Ankara\'daki DTCF\'deki görevlerinden uzaklaştırılmaları', ['Birlikte Malta\'ya sürgün edilmeleri', 'İstanbul Darülfünunu\'nun ilk sosyoloji kürsüsünü birlikte kurmuş olmaları', 'Birlikte Durkheim\'ın öğrencisi olmaları'], 'Bu üç akademisyen 1948\'de siyasi görüşleri gerekçesiyle DTCF\'den uzaklaştırıldı. Berkes daha sonra Kanada\'da McGill Üniversitesi\'nde çalıştı.'),
  ('Niyazi Berkes\'in Türkiye\'den ayrıldıktan sonra uzun yıllar öğretim üyeliği yaptığı ve İslam Araştırmaları Enstitüsü\'nde çalıştığı üniversite hangisidir?', 'McGill Üniversitesi', ['Oxford Üniversitesi', 'Sorbonne Üniversitesi', 'Chicago Üniversitesi'], 'Berkes 1952\'den itibaren Kanada\'daki McGill Üniversitesi\'nde çalıştı; "Türkiye\'de Çağdaşlaşma" eseri de bu dönemde İngilizce olarak yazıldı.'),
  ('Sabri Ülgener\'in "İktisadi Çözülmenin Ahlak ve Zihniyet Dünyası" adlı eserinde Osmanlı ekonomik zihniyetini incelerken en çok hangi sosyoloğun yaklaşımından yararlandığı kabul edilir?', 'Max Weber', ['Auguste Comte', 'Herbert Spencer', 'Gabriel Tarde'], 'Ülgener, Weber\'in din-ekonomi ilişkisine ve zihniyet kavramına dayanarak Osmanlı esnafının ve tasavvufi ahlakın iktisadi davranışla ilişkisini inceledi.'),
  ('Nilüfer Göle\'nin Türkiye\'de modernleşme ile din arasındaki ilişkiyi üniversiteli başörtülü kadınlar üzerinden incelediği 1991 tarihli eseri hangisidir?', 'Modern Mahrem', ['Türkiye\'de Çağdaşlaşma', 'Kültür Değişmeleri', 'Ereğli'], 'Nilüfer Göle "Modern Mahrem"de dindar kadınların kamusal alanda görünür hale gelişini modernlik ile mahremiyet arasındaki gerilim üzerinden tartıştı.'),
  ('İbrahim Yasa\'nın 1950\'lerde Ankara yakınlarında yaptığı ve Türk köy sosyolojisinin klasik monografilerinden sayılan araştırması hangi köyü konu alır?', 'Hasanoğlan', ['Ereğli', 'Balgat', 'Sakaltutan'], 'İbrahim Yasa\'nın "Hasanoğlan Köyü" araştırması, köy enstitüsünün bulunduğu bu köyün toplumsal ve ekonomik yapısını ayrıntılı biçimde betimler.'),
  ('Amerikalı sosyolog Daniel Lerner\'in "Geleneksel Toplumun Çöküşü" adlı eserinde Ankara yakınlarındaki Balgat köyünde "bakkal" ile "muhtar" figürlerini karşılaştırmasının amacı hangisidir?', 'Modernleşmeyle değişen zihniyeti ve empati yeteneğini göstermek', ['Köydeki dinsel çatışmaları belgelemek', 'Köydeki tarımsal üretim tekniklerini kent sanayisiyle karşılaştırmak', 'Köyün nüfus sayımını yapmak'], 'Lerner, dış dünyayla ilgilenen ve kendini başka rollerde düşünebilen bakkalı modern, geleneksel değerlere bağlı muhtarı ise geleneksel insan tipi olarak sundu.'),
  ('Ziya Gökalp\'in öğrencisi olan ve 1923\'te "Milliyet Nazariyeleri ve Millî Hayat" adlı eseri yayımlanan sosyolog kimdir?', 'Mehmet İzzet', ['Hilmi Ziya Ülken', 'Niyazi Berkes', 'Mümtaz Turhan'], 'Mehmet İzzet, Darülfünun\'da sosyoloji okutmuş ve milliyet kuramlarını sistemli biçimde ele aldığı eseriyle tanınmıştır. Genç yaşta öldü.'),
  ('İsmail Hakkı Baltacıoğlu\'nun 1934\'ten itibaren uzun yıllar çıkardığı ve eğitim, kültür ve toplum konularını işlediği dergi hangisidir?', 'Yeni Adam', ['Kadro', 'Ülkü', 'Servet-i Fünun'], 'Baltacıoğlu, okulun toplumsal yaşamla bütünleşmesini savunan "içtimai mektep" anlayışını Yeni Adam dergisinde yaydı. Kadro dergisi ise Şevket Süreyya Aydemir ve arkadaşlarınındır.'),
  ('Hilmi Ziya Ülken\'in, uygarlıkların uyanış dönemlerinde çeviri faaliyetlerinin oynadığı rolü incelediği eseri hangisidir?', 'Uyanış Devirlerinde Tercümenin Rolü', ['Türkiye\'de Çağdaşlaşma', 'Garplılaşmanın Neresindeyiz?', 'Toplumsal Yapı Araştırmaları'], 'Ülken bu eserinde Abbasi, Rönesans ve Tanzimat gibi dönemlerde çevirinin düşünsel uyanışı nasıl beslediğini karşılaştırmalı olarak ele aldı.'),
  ('Emre Kongar\'ın toplumsal değişmeyi açıklayan kuramları sınıflandırıp Türkiye\'ye uygulamayı amaçladığı eseri hangisidir?', 'Toplumsal Değişme Kuramları ve Türkiye Gerçeği', ['Türkiye Nasıl Kurtarılabilir?', 'İktisadi Çözülmenin Ahlak ve Zihniyet Dünyası', 'Kültür Değişmeleri'], 'Kongar bu eserinde toplumsal değişme kuramlarını tarihsel ve kuramsal açıdan sınıflandırarak Türk toplumunun dönüşümünü açıklamada kullandı.'),
  ('Albion Small\'un 1895\'te kurduğu ve dünyanın en eski sosyoloji dergilerinden sayılan yayın hangisidir?', 'American Journal of Sociology', ['American Sociological Review', 'British Journal of Sociology', 'Social Forces'], 'American Journal of Sociology Chicago Üniversitesi\'nde yayımlanmaya başladı. American Sociological Review ise 1936\'da Amerikan Sosyoloji Derneği tarafından çıkarıldı.'),
  ('Robert Park\'ın ırk ilişkileri döngüsüne göre farklı gruplar arasındaki ilişkiler hangi aşamalardan geçer?', 'Temas, rekabet, uzlaşma, asimilasyon', ['Asimilasyon, temas, çatışma, rekabet', 'Rekabet, asimilasyon, temas, uzlaşma', 'Uzlaşma, rekabet, temas, asimilasyon'], 'Park\'a göre gruplar önce temas kurar, ardından kaynaklar için rekabete girer, sonra bir uzlaşma (uyum) düzeni kurulur ve süreç asimilasyonla sonuçlanır.'),
  ('Nels Anderson\'ın evsiz gezici işçiler arasında yaşayarak yazdığı ve Chicago Okulu\'nun katılımcı gözlem geleneğinin ilk örneklerinden sayılan 1923 tarihli eseri hangisidir?', 'The Hobo', ['The Gang', 'Street Corner Society', 'Middletown'], 'Anderson, "The Hobo"da işten işe dolaşan göçebe işçilerin yaşamını içeriden betimledi. "The Gang" Thrasher\'a, "Street Corner Society" Whyte\'a, "Middletown" ise Lynd çiftine aittir.'),
  ('W. I. Thomas\'a göre insan davranışını yönlendiren "dört dilek" arasında hangisi yer alır?', 'Yeni deneyim isteği', ['Artı değer elde etme isteği', 'Kolektif coşku isteği', 'Kader öğretisine uyma isteği'], 'Thomas insanların yeni deneyim, güvenlik, tanınma ve karşılık görme (yakınlık) dileklerinin davranışları yönlendirdiğini ileri sürdü.'),
  ('Blumer\'in, araştırmacıya kesin tanımlar yerine neye bakacağı konusunda genel bir yön veren kavramlar için kullandığı terim hangisidir?', 'Duyarlılaştırıcı kavramlar', ['Operasyonel tanımlar', 'İdeal tipler', 'Açık işlevler'], 'Blumer kesin ölçütlerle tanımlanan kavramların toplumsal yaşamı kavramada yetersiz kaldığını, araştırmacıyı olgulara duyarlı kılan esnek kavramların daha uygun olduğunu savundu.'),
  ('Sembolik etkileşimciliğin Iowa Okulu\'nu temsil eden Manford Kuhn\'un, kişilere "Ben kimim?" sorusuna yirmi yanıt yazdırarak benliği ölçmeye çalıştığı araç hangisidir?', 'Yirmi İfade Testi', ['Bogardus Sosyal Mesafe Ölçeği', 'Rorschach Mürekkep Lekesi Testi', 'Likert Tutum Ölçeği'], 'Kuhn, Chicago geleneğinin nitel yaklaşımından farklı olarak benliği ölçülebilir kılmaya çalıştı. Yirmi İfade Testi bu amaçla geliştirildi.'),
  ('Charles H. Cooley\'in birincil grup kavramını ayrıntılı biçimde tanıttığı 1909 tarihli eseri hangisidir?', 'Toplumsal Örgütlenme', ['Toplumsal Sistem', 'Toplumsal Eylemin Yapısı', 'Toplumsal Sözleşme'], 'Cooley "Social Organization" (Toplumsal Örgütlenme) adlı eserinde aile, oyun grubu ve komşuluk gibi yüz yüze ve sıcak ilişkilere dayanan grupları birincil grup olarak tanımladı.'),
  ('Goffman\'ın "Damga" (Stigma) adlı eserinde yaptığı ayrıma göre, damgası dışarıdan hemen görülemeyen ve bu yüzden bilginin ortaya çıkıp çıkmayacağını yönetmek zorunda olan kişi nasıl nitelendirilir?', 'Gözden düşebilir (itibarı sarsılabilir) kişi', ['Gözden düşmüş (itibarı sarsılmış) kişi', 'Toplumun genelleştirilmiş ötekisi rolündeki kişi', 'Marjinal insan'], 'Goffman damgası açıkça bilinen kişiyi "gözden düşmüş", damgası gizli kalabilen kişiyi ise "gözden düşebilir" olarak ayırır. İkincisi için asıl sorun bilgiyi denetlemektir.'),
  ('Goffman\'ın damga türleri arasında ırk, ulus ya da dinden kaynaklanan ve aile yoluyla kuşaktan kuşağa geçebilen damgaya verdiği ad hangisidir?', 'Kabilesel damga', ['Bedensel damga', 'Karakter damgası', 'Mesleki damga'], 'Goffman damgayı bedensel kusurlar, karakter kusurları olarak algılanan özellikler ve ırk, ulus, din gibi kabilesel özellikler olmak üzere üç türe ayırır.'),
  ('Goffman\'ın akıl hastanesi gözlemlerine dayanan "Tımarhaneler" (Asylums) adlı eserinde, kuruma girenlerin kişisel eşyalarının alınması, tek tip giysi giydirilmesi gibi uygulamalarla eski kimliklerinden koparılmasına verdiği ad hangisidir?', 'Benliğin aşağılanması', ['Ayna benlik', 'Rol kümesi', 'Kolektif coşkunun kurumsallaşması'], 'Goffman total kurumlarda yeni gelenin önceki kimliğini destekleyen her şeyden arındırıldığını ve benliğinin sistemli biçimde aşağılandığını gösterdi.'),
  ('Goffman\'ın etkileşimde bireylerin hem kendilerinin hem de karşılarındakinin olumlu imajını korumak için gösterdiği çabayı anlatan kavramı hangisidir?', 'Yüz çalışması', ['Duygusal emek', 'Kolektif bilinç', 'Sembolik şiddet'], 'Goffman, kişilerin etkileşim boyunca "yüz"lerini, yani toplumca onaylanan imajlarını korumaya çalıştığını; utanç verici durumları birlikte onarmaya uğraştığını gösterdi.'),
  ('Goffman\'ın 1974 tarihli "Çerçeve Çözümlemesi" adlı eserinin temel sorusu hangisidir?', 'İnsanlar karşılaştıkları durumu hangi yorum şemalarıyla tanımlar?', ['Toplumlar hangi üretim tarzlarından geçer?', 'Bireyler toplumsal sınıflara nasıl ayrılır?', 'Nüfus artışı işbölümünü nasıl etkiler?'], 'Goffman çerçeveyi, bireylerin "Burada neler oluyor?" sorusuna yanıt verirken kullandığı yorum şemaları olarak tanımlar; aynı olay şaka, oyun ya da kavga olarak çerçevelenebilir.'),
  ('Etnometodolojideki "indekslilik" kavramı neyi anlatır?', 'Bir sözün anlamının ancak söylendiği bağlam bilindiğinde anlaşılabilmesini', ['Toplumsal olguların istatistiksel indeksler ve göstergeler aracılığıyla ölçülmesini', 'Bireylerin gelirlerine göre sıralanmasını', 'Kurumların hiyerarşik bir dizinde yer almasını'], '"Ben", "burada", "yarın" gibi ifadelerin anlamı kim tarafından, nerede ve ne zaman söylendiğine bağlıdır. Garfinkel\'e göre gündelik dilin büyük bölümü böyle bağlama bağlıdır.'),
  ('Harvey Sacks\'ın etnometodolojiden yola çıkarak geliştirdiği ve sıra alma gibi gündelik konuşmanın düzenini ayrıntılı kayıtlarla inceleyen yaklaşım hangisidir?', 'Konuşma çözümlemesi', ['İçerik analizi', 'Söylem analizi', 'Göstergebilim'], 'Konuşma çözümlemesi, kayda alınmış gündelik konuşmalarda konuşmacıların sözü nasıl devraldığını, kesintileri nasıl onardığını ve sohbeti nasıl açıp kapattığını inceler.'),
  ('Schutz\'un "Eve Dönen" adlı denemesinde, uzun süre uzakta kaldıktan sonra evine dönen askerin yaşadığı güçlüğün kaynağı hangisidir?', 'Hem kendisinin hem evdekilerin değişmesiyle ortak deneyimlerin eskimesi', ['Evin fiziksel olarak yıkılmış olması', 'Devletin askere hiçbir hak tanımaması', 'Askerin yabancı bir dili unutmuş olması'], 'Schutz, dönen kişinin evdeki yaşamı ayrıldığı gibi bulmayı beklediğini, oysa hem kendisinin hem de evdekilerin farklı deneyimlerle değiştiğini; ortak tipleştirmelerin yeniden kurulması gerektiğini gösterir.'),
  ('Peter Berger\'in dinin insanlara anlamlı bir dünya düzeni sağlayan koruyucu işlevini anlatmak için kullandığı ve eserine ad olarak verdiği benzetme hangisidir?', 'Kutsal şemsiye (kutsal örtü)', ['Demir kafes', 'Halkın afyonu', 'Kutsal ağaç (hayat ağacı)'], 'Berger 1967 tarihli "The Sacred Canopy"de dinin toplumun kurduğu dünyaya kozmik bir anlam ve meşruiyet kazandırdığını, kaosa karşı bir örtü işlevi gördüğünü savundu.'),
  ('Merton\'a göre bir toplumsal gereksinimi karşılayan bir kurumun yerini, aynı gereksinimi karşılayabilecek başka bir kurumun alabilmesi hangi kavramla anlatılır?', 'İşlevsel alternatif', ['İşlev bozukluğu', 'Örtük işlev', 'Kolektif tasavvurun yeniden üretimi'], 'Merton, işlevselciliğin "her kurum vazgeçilmezdir" varsayımını eleştirdi; bir işlevin farklı kurumlar tarafından da yerine getirilebileceğini işlevsel alternatif kavramıyla gösterdi.'),
  ('Merton\'un bir kasabadaki etkili kişileri incelerken yaptığı ayrıma göre, ilgisini yerel sorunlara yoğunlaştıran ve etkisini geniş tanıdık ağından alan kişi hangisidir?', 'Yerel etkili', ['Kozmopolit etkili', 'Marjinal insan', 'Kapı bekçisi'], 'Merton yerel etkilileri kasabaya kök salmış ve çok sayıda kişiyi tanıyan, kozmopolit etkilileri ise dış dünyaya ilişkin bilgi ve uzmanlığıyla etkili olan kişiler olarak ayırdı.'),
  ('Paul Lazarsfeld ile Merton\'un radyo propagandası üzerine çalışırken geliştirdikleri ve günümüzde odak grup tekniğinin öncüsü sayılan yöntem hangisidir?', 'Odaklanmış görüşme', ['Yapılandırılmış anket', 'Katılımcı gözlem', 'Deneysel tasarım'], 'Merton, katılımcıların belirli bir uyarıcıya, örneğin bir radyo programına verdikleri tepkileri derinlemesine konuşturan odaklanmış görüşme yöntemini geliştirdi.'),
  ('Niklas Luhmann\'ın sistem kuramına göre toplumsal sistemlerin temel öğesi nedir?', 'İletişimler', ['Tek tek insanlar', 'Binalar ve araçlar', 'Kalıtsal özellikler'], 'Luhmann\'a göre toplum insanlardan değil iletişimlerden oluşur; insanlar toplumsal sistemin çevresinde yer alan psişik sistemlerdir.'),
  ('Luhmann\'ın biyolog Maturana ve Varela\'dan ödünç aldığı ve sistemlerin kendi öğelerini kendi işleyişleriyle yeniden ürettiğini anlatan kavram hangisidir?', 'Otopoiesis', ['Homeostazi', 'Entropi artışı', 'Simbiyoz'], 'Otopoiesis, kendi kendini üretme anlamına gelir. Luhmann\'a göre hukuk, ekonomi ya da bilim gibi sistemler kendi iletişimlerini kendi kodlarıyla üreterek varlığını sürdürür.'),
  ('Luhmann\'a göre modern toplumda hukuk sistemi olayları hangi ikili koda göre işler?', 'Hukuka uygun / hukuka aykırı', ['Doğru / yanlış', 'Ödeme / ödememe', 'İktidar / muhalefet ayrımı'], 'Luhmann her işlevsel alt sistemin kendine özgü bir ikili kodu olduğunu savunur: bilimde doğru-yanlış, ekonomide ödeme-ödememe, siyasette iktidar-muhalefet, hukukta hukuka uygun-aykırı.'),
  ('Luhmann\'a göre toplumsal sistemlerin çevrelerine karşı temel işlevi hangisidir?', 'Çevrenin karmaşıklığını azaltarak seçilebilir olanakları sınırlamak', ['Çevredeki bütün olayları eksiksiz kopyalamak', 'Çevreyle sınırlarını tümüyle ortadan kaldırmak', 'Bireylerin bütün isteklerini ayrım gözetmeden ve eşit biçimde karşılamak'], 'Luhmann\'a göre dünya sonsuz olanaklarla doludur; sistemler bu karmaşıklığı seçici biçimde azaltarak anlamlı ve yönetilebilir bir düzen kurar.'),
  ('Coser\'in ayrımına göre belirli bir hedefe ulaşmak için araç olarak kullanılan, örneğin ücret artışı için yapılan grev hangi tür çatışmadır?', 'Gerçekçi çatışma', ['Gerçekçi olmayan çatışma', 'Kurumsal çatışma', 'Simgesel çatışma'], 'Coser\'e göre gerçekçi çatışma, belirli taleplerin karşılanmasına yöneliktir ve başka araçlarla da çözülebilir. Gerçekçi olmayan çatışma ise yalnızca gerilimi boşaltma amacı taşır.'),
  ('Dahrendorf\'un, içinde emir verenler ile emir alanlar arasında otorite ilişkisi bulunan devlet, şirket ya da kilise gibi örgütler için kullandığı kavram hangisidir?', 'Zorunlu eşgüdümlü birlikler', ['Birincil gruplar', 'Gönüllü ve kendiliğinden dernekler', 'Referans grupları'], 'Dahrendorf\'a göre her zorunlu eşgüdümlü birlikte otoriteye sahip olanlar ile olmayanlar arasında çıkar çatışması doğar.'),
  ('C. Wright Mills "Sosyolojik Muhayyile" adlı eserinde Parsons\'ın kuramını hangi adla eleştirmiştir?', 'Büyük kuram', ['Orta erimli kuram', 'Soyutlanmış görgücülük', 'Etiketleme kuramı'], 'Mills, Parsons\'ın kavram yığınına dayanan soyut sistemini "büyük kuram" olarak, verilerin kuramsız biriktirilmesini ise "soyutlanmış görgücülük" olarak eleştirdi.'),
  ('Hirschi\'ye göre bireyi topluma bağlayan ve suçtan alıkoyan dört öğe arasında hangisi yer alır?', 'Geleneksel etkinliklere katılım', ['Sapkın akranlarla yakın ilişki', 'Amaçlarla araçlar arasındaki gerilim', 'Kalabalık içinde anonimlik'], 'Hirschi\'nin toplumsal bağ öğeleri bağlanma, adanmışlık, geleneksel etkinliklere katılım ve inançtır. Okul ve spor etkinliklerine katılan gencin suça ayıracak zamanı ve isteği azalır.'),
  ('Frankfurt Okulu\'nun kurumsal çatısını oluşturan Toplumsal Araştırmalar Enstitüsü hangi yılda kurulmuştur?', '1923', ['1905', '1945', '1968'], 'Enstitü 1923\'te Frankfurt\'ta kuruldu; 1930\'da Max Horkheimer\'ın müdürlüğüyle eleştirel kuramın merkezi haline geldi.'),
  ('Walter Benjamin\'in Baudelaire\'den yola çıkarak modern kentin kalabalıklarında amaçsızca dolaşıp kenti seyreden figür için kullandığı kavram hangisidir?', 'Flanör', ['Dandi', 'Bohem', 'Yabancı'], 'Benjamin Paris pasajları üzerine çalışmasında flanörü, kent kalabalığının içinde kaybolmadan onu gözlemleyen modern kentli tipi olarak inceledi.'),
  ('Habermas\'ın "Bilgi ve İnsan İlgileri" adlı eserinde eleştirel toplum bilimlerini yönlendirdiğini ileri sürdüğü bilgi ilgisi hangisidir?', 'Özgürleştirici ilgi', ['Teknik ilgi', 'Pratik (yorumsayıcı) ilgi', 'Estetik ilgi'], 'Habermas doğa bilimlerini teknik, tarih ve yorum bilimlerini pratik, eleştirel toplum kuramını ve psikanalizi ise özgürleştirici bilgi ilgisiyle ilişkilendirdi.'),
  ('Frankfurt Okulu\'nun üçüncü kuşağından Axel Honneth\'in Hegel\'den yola çıkarak geliştirdiği ve toplumsal mücadelelerin kökenini açıklayan kavram hangisidir?', 'Tanınma', ['Yabancılaşma', 'Rasyonelleşme', 'Ekonomik sömürü ve artı değer'], 'Honneth\'e göre sevgi, haklar ve toplumsal değer görme biçimindeki tanınma talepleri çiğnendiğinde insanlar aşağılanma duygusuyla mücadeleye girişir.'),
  ('Gramsci\'nin, sivil toplumun güçlü olduğu Batı toplumlarında iktidarı ele geçirmek için önerdiği uzun soluklu kültürel mücadele stratejisi hangisidir?', 'Mevzi savaşı', ['Manevra savaşı', 'Sürekli devrim', 'Gerilla savaşı'], 'Gramsci, Rusya\'daki gibi devlete doğrudan saldırının (manevra savaşı) Batı\'da işe yaramayacağını, önce sivil toplumda kültürel ve ahlaki önderliği kazanmak gerektiğini savundu.'),
  ('Althusser\'e göre ideolojinin bireyleri belirli kimliklere sahip özneler olarak kurmasını anlatan kavram hangisidir?', 'Çağırma', ['Şeyleşme', 'Kendini doğrulayan kehanet', 'Toplumsal kapanma'], 'Althusser\'in örneğinde sokakta bir polis "Hey, sen!" diye seslendiğinde dönüp bakan kişi, kendini çağrılan özne olarak tanır. İdeoloji de bireyleri benzer biçimde özneye dönüştürür.'),
  ('Georg Lukács\'ın "Tarih ve Sınıf Bilinci" adlı eserinde Marx\'ın meta fetişizminden geliştirdiği ve insan ilişkilerinin ve niteliklerinin nesne gibi algılanmasını anlatan kavram hangisidir?', 'Şeyleşme', ['Rasyonelleşme', 'Asabiyet', 'Farklılaşma'], 'Lukács\'a göre kapitalizmde metalaşma bütün toplumsal yaşama yayılır; insanlar kendi ürettikleri ilişkileri değiştirilemez doğal şeyler gibi görmeye başlar.'),
  ('Bourdieu\'nün kültürel sermaye türlerinden, üniversite diploması gibi resmî belgelerle onaylanan biçimine ne ad verilir?', 'Kurumsallaşmış kültürel sermaye', ['Bedenselleşmiş kültürel sermaye', 'Nesneleşmiş kültürel sermaye', 'Simgesel ve ekonomik karma sermaye'], 'Bourdieu kültürel sermayeyi bireyde kalıcı eğilimler olarak bedenselleşmiş, tablo ve kitap gibi nesnelerde nesneleşmiş, diploma ve unvanlarla kurumsallaşmış biçimlerde inceler.'),
  ('Bourdieu\'nün bir toplumda tartışılmadan, sorgulanmadan doğal kabul edilen inanç ve varsayımlar bütünü için kullandığı kavram hangisidir?', 'Doxa', ['Ethos', 'Logos', 'Telos'], 'Doxa, "her şey olduğu gibi olmalıdır" duygusunu yaratan, sorgulanmayan ortak kanılar alanıdır. Ortodoksi ve heterodoksi ancak doxa sorgulanmaya başladığında ortaya çıkar.'),
  ('Bourdieu\'nün Jean-Claude Passeron ile birlikte yazdığı ve eğitim sisteminin toplumsal eşitsizlikleri nasıl kuşaktan kuşağa aktardığını çözümleyen 1970 tarihli eseri hangisidir?', 'Yeniden Üretim', ['Ayrım', 'Pratik Bir Kuramın Taslağı', 'Akademik İnsan'], '"Yeniden Üretim" eğitimde pedagojik eylemin sembolik şiddet olarak işlediğini ve egemen kültürü meşrulaştırdığını ileri sürer.'),
  ('Foucault\'nun "Deliliğin Tarihi"nde 17. yüzyılda yoksulların, işsizlerin ve delilerin topluca kurumlara kapatılmasını anlatmak için kullandığı ifade hangisidir?', 'Büyük Kapatılma', ['Büyük Dönüşüm', 'Büyük Göç', 'Büyük Bunalım Dönemi'], 'Foucault, 1656\'da Paris\'te Genel Hastane\'nin kurulmasıyla başlayan dönemde aklın "öteki"si sayılan grupların toplumdan yalıtılarak kapatıldığını gösterdi.'),
  ('Foucault\'nun tarihsel çözümlemelerinde Nietzsche\'den aldığı ve bugün apaçık sayılan kavram ve kurumların tesadüfi, iktidar ilişkilerine bağlı oluşumunu izleyen yönteme ne ad verilir?', 'Soybilim', ['Fenomenoloji', 'Diyalektik materyalizm', 'Yapısal işlevselcilik'], 'Foucault soybilimle, değişmez görünen olguların kökeninin aslında rastlantılar, çatışmalar ve iktidar ilişkileriyle örüldüğünü gösterir.'),
  ('Foucault\'nun devletin yalnızca yasa ve zorla değil, bireylerin kendilerini yönetme biçimlerini yönlendiren teknikler aracılığıyla nüfusu yönetmesini anlatan kavramı hangisidir?', 'Yönetimsellik', ['Bürokratikleşme', 'Rasyonelleşme', 'Kurumsal farklılaşma'], 'Yönetimsellik, istatistik, sağlık politikaları ve öz denetim teknikleriyle insanların davranışlarının uzaktan biçimlendirilmesini anlatır.'),
  ('Anthony Giddens\'ın "Modernliğin Sonuçları" adlı eserinde para ve uzman sistemleri gibi mekanizmaların toplumsal ilişkileri yerel bağlamlarından koparmasına verdiği ad hangisidir?', 'Yerinden çıkarma', ['İstila ve ardıllık', 'Kültürel gecikme', 'Seçkinlerin dolaşımı'], 'Giddens\'a göre modernlikte ilişkiler yüz yüze yerel bağlamlardan koparılarak geniş zaman-mekân aralıklarına yayılır; para gibi simgesel işaretler ve uzman sistemleri bunu sağlar.'),
  ('Giddens\'ın bireyin dünyanın sürekliliğine ve kendi kimliğine ilişkin temel güven duygusunu anlatan kavramı hangisidir?', 'Ontolojik güvenlik', ['Toplumsal güvenlik sistemi', 'Kolektif bilinç', 'Statü tutarlılığı'], 'Ontolojik güvenlik, gündelik rutinlerin ve tanıdık çevrenin sağladığı, "dünya olduğu gibi kalacak" duygusudur. Giddens\'a göre modernlik bu güveni sürekli sınar.'),
  ('Giddens\'ın ayrımına göre insanların nasıl yapılacağını sözle açıklayamadıkları halde gündelik yaşamda ustalıkla uyguladıkları bilgiye ne ad verilir?', 'Pratik bilinç', ['Söylemsel bilinç', 'Kolektif bilinç', 'Sınıf bilinci'], 'Giddens\'a göre aktörler pek çok kuralı açıkça ifade edemeden, pratik bilinç düzeyinde bilir ve uygular; söylemsel bilinç ise sözle anlatılabilen bilgidir.'),
  ('Bauman\'ın küreselleşme çözümlemesinde dünyada özgürce dolaşabilen ayrıcalıklıları "turist", dolaşmak zorunda kalan ama sınırlarda durdurulanları ise hangi adla nitelendirir?', 'Serseriler', ['Hacılar', 'Göçebe çobanlar', 'Flanörler'], 'Bauman\'a göre küreselleşme hareketliliği eşitsiz dağıtır: turistler isteyerek ve hoş karşılanarak gezer, serseriler ise zorunlulukla yer değiştirir ve istenmez.'),
  ('Elias\'ın, XIV. Louis dönemi Fransız sarayında soyluların görgü kuralları ve rütbe yarışıyla nasıl denetim altına alındığını incelediği eseri hangisidir?', 'Saray Toplumu', ['Uygarlık Süreci', 'Kurulu Düzenler ve Yabancılar', 'Sporda Heyecan Arayışı'], 'Elias "Saray Toplumu"nda, savaşçı soyluların saray etiketi içinde birbirine bağımlı ve kraldan saygınlık bekleyen saraylılara dönüşmesini inceledi.'),
  ('Fredric Jameson\'ın postmodernizmi çözümlediği eserinin adında yer alan ve postmodern kültürü ekonomik bir aşamaya bağlayan kavram hangisidir?', 'Geç kapitalizm', ['Erken kapitalizm', 'Feodalizm', 'Ticari kapitalizm'], 'Jameson\'ın "Postmodernizm ya da Geç Kapitalizmin Kültürel Mantığı" adlı eseri, postmodern kültürü çok uluslu tüketim kapitalizminin kültürel ifadesi olarak görür.'),
  ('David Harvey\'in "Postmodernliğin Durumu" adlı eserinde, ulaşım ve iletişim teknolojileri sayesinde mesafelerin ve sürelerin hızla kısalmasını anlatan kavramı hangisidir?', 'Zaman-mekân sıkışması', ['Zaman-mekân uzaklaşması', 'Kültürel gecikme', 'İstila ve ardıllık'], 'Harvey, sermayenin daha hızlı dolaşım arayışının dünyayı küçülttüğünü ve bu sıkışmanın postmodern kültürel deneyimi biçimlendirdiğini savundu.'),
  ('Manuel Castells\'in ağ toplumu çözümlemesinde finans, enformasyon ve sermayenin coğrafi yakınlık gerektirmeden dolaştığı yeni mekânsal mantığa verdiği ad hangisidir?', 'Akışlar uzamı', ['Yerler uzamı', 'Geçiş bölgesi', 'Kamusal alanın yapısı'], 'Castells\'e göre güç ve zenginlik akışlar uzamında örgütlenirken, insanların çoğu gündelik yaşamlarını hâlâ yerel "yerler uzamı"nda sürdürür.'),
  ('Patricia Hill Collins\'in ırk, cinsiyet ve sınıf baskılarının birbirine bağlı biçimde örgütlenmesini anlatmak için kullandığı kavram hangisidir?', 'Tahakküm matrisi', ['Demir kafes', 'Akışlar uzamı', 'Yapının ikiliği ilkesi'], 'Collins "Siyah Feminist Düşünce" adlı eserinde baskı biçimlerinin yapısal, disipliner, hegemonik ve kişilerarası alanlarda iç içe örgütlendiğini tahakküm matrisi kavramıyla açıkladı.'),
  ('Sylvia Walby\'nin ataerkilliği tek bir nedene indirgemeyip ücretli iş, ev içi üretim, devlet, şiddet, cinsellik ve kültür gibi kaç ayrı yapı üzerinden çözümlediği bilinir?', 'Altı', ['İki', 'Dört', 'Sekiz'], 'Walby "Ataerkilliği Kuramlaştırmak" adlı eserinde ataerkilliği birbiriyle etkileşen altı yapı üzerinden inceledi ve özel ataerkillikten kamusal ataerkilliğe geçişi tartıştı.'),
  ('Judith Butler\'ın toplumsal cinsiyetin önceden var olan bir öz değil, tekrarlanan söz ve eylemlerle sürekli üretilen bir şey olduğunu anlatan kavramı hangisidir?', 'Performatiflik', ['Ayna benlik süreci', 'Kolektif bilinç', 'İdeal tip'], 'Butler "Cinsiyet Belası"nda kadınlık ve erkekliğin, normlara uygun davranışların sürekli tekrarı yoluyla kurulduğunu ve doğal görünmeye başladığını savundu.'),
  ('W. E. B. Du Bois\'nın 1899\'da yayımlanan ve Philadelphia\'daki siyah topluluğun yaşam koşullarını kapı kapı dolaşarak topladığı verilerle inceleyen eseri hangisidir?', 'Philadelphia\'daki Zenciler', ['Siyah Halkın Ruhu', 'Bir Amerikan İkilemi: Zenci Sorunu', 'Görünmez Adam'], '"The Philadelphia Negro" ABD\'de kent topluluğuna ilişkin ilk sistemli görgül sosyolojik araştırmalardan biridir. "Bir Amerikan İkilemi" Myrdal\'a, "Görünmez Adam" Ellison\'a aittir.'),
  ('Robert Park\'ın öğrencisi olup Chicago\'daki siyah aileler üzerine çalışmalarıyla tanınan ve Howard Üniversitesi\'nde uzun yıllar sosyoloji okutan sosyolog kimdir?', 'E. Franklin Frazier', ['W. Lloyd Warner', 'William Fielding Ogburn', 'Robert Redfield'], 'E. Franklin Frazier "ABD\'de Siyah Aile" adlı eseriyle tanınır ve Amerikan Sosyoloji Derneği\'ne başkanlık eden ilk Afrikalı Amerikalıdır.'),
  ('Amerikan Sosyoloji Derneği\'nin ilk başkanı olan ve Sumner\'ın aksine toplumsal ilerlemenin bilinçli planlama ve devlet müdahalesiyle hızlandırılabileceğini savunan sosyolog kimdir?', 'Lester F. Ward', ['Albion Small', 'Franklin Giddings', 'Edward A. Ross'], 'Lester Ward toplumun akıl yoluyla yönlendirilmesini "telesis" kavramıyla anlattı ve eğitime büyük önem verdi. 1906\'da Amerikan Sosyoloji Derneği\'nin ilk başkanı oldu.'),
  ('Veblen\'in "Aylak Sınıfın Teorisi"nde zenginlerin çalışmak zorunda olmadıklarını göstermek için zamanlarını üretken olmayan uğraşlarla geçirmesine verdiği ad hangisidir?', 'Gösterişçi boş zaman', ['Gösterişçi tüketim', 'Eğitilmiş yetersizlik', 'Sahte ihtiyaç'], 'Veblen\'e göre ölü dilleri öğrenmek, görgü kurallarında ustalaşmak ya da spor ve av gibi uğraşlar, kişinin emek harcamadan yaşayabildiğini gösteren gösterişçi boş zaman biçimleridir.'),
  ('Veblen\'in, bir kişinin aldığı eğitim ve deneyimin onu yeni ve farklı durumlarda yanlış davranmaya yatkın hale getirmesini anlatan kavramı hangisidir?', 'Eğitilmiş yetersizlik', ['Kültürel gecikme kuramı', 'Gösterişçi boş zaman', 'Rol mesafesi'], 'Veblen\'in ortaya attığı ve Merton\'un bürokrasi eleştirisinde kullandığı bu kavram, bir zamanlar başarılı olan becerilerin değişen koşullarda körlüğe dönüşmesini anlatır.'),
  ('Mannheim\'ın, belirli bir sınıfa sıkı sıkıya bağlı olmadıkları için farklı bakış açılarını birleştirme olanağına sahip olduğunu düşündüğü toplumsal kesim hangisidir?', 'Görece bağımsız aydınlar', ['Toprak sahibi soylular', 'Din adamları', 'Fabrika işçileri'], 'Mannheim, eğitim yoluyla bir araya gelen ve farklı sınıflardan gelen aydınların, tek bir sınıfın bakışına hapsolmadan daha bütünlüklü bir bakış geliştirebileceğini savundu.'),
  ('Şerif Mardin\'in Türk siyasetini çözümlediği merkez-çevre kavramlarını ödünç aldığı Amerikalı sosyolog kimdir?', 'Edward Shils', ['Talcott Parsons', 'Robert Merton', 'Daniel Bell'], 'Mardin, Edward Shils\'in toplumlarda değerlerin ve kurumların merkezi ile bu merkeze uzak çevre arasındaki ayrımına dayanan kavramlarını Osmanlı-Türk deneyimine uyguladı.'),
  ('Stuart Hall\'un kodlama/kod açma modeline göre bir televizyon haberini yapımcının amaçladığı anlamı kısmen kabul edip kendi yerel koşullarına göre uyarlayarak yorumlayan izleyicinin okuması hangisidir?', 'Müzakereci okuma', ['Egemen-hegemonik okuma', 'Karşıt okuma', 'Edilgen okuma'], 'Hall izleyicilerin mesajı egemen anlamıyla, müzakereci biçimde ya da tümüyle karşıt bir çerçeveyle okuyabileceğini gösterdi; medya izleyicisini edilgen saymayan bir yaklaşım geliştirdi.'),
  ('James Coleman\'ın 1990 tarihli "Toplumsal Kuramın Temelleri" adlı eseri hangi kuramsal yaklaşımın en kapsamlı sosyolojik ifadelerinden sayılır?', 'Rasyonel seçim kuramı', ['Sembolik etkileşimcilik', 'Eleştirel kuram', 'Postyapısalcılık'], 'Coleman, bireylerin amaçlı ve çıkarlarını gözeten eylemlerinden yola çıkarak makro toplumsal olguları açıklamaya çalışan rasyonel seçim kuramını sistemleştirdi.'),
  ('Mark Granovetter\'ın 1985 tarihli makalesinde ekonomik eylemlerin soyut piyasa kararları değil, süregiden kişisel ilişki ağları içinde gerçekleştiğini anlatmak için kullandığı kavram hangisidir?', 'Gömülülük', ['Şeyleşme', 'Kapanma', 'Zaman-mekân sıkışması'], 'Granovetter, ekonomistlerin yalıtılmış birey varsayımına da aşırı toplumsallaşmış birey anlayışına da karşı çıkarak ekonomik davranışın toplumsal ilişkilere gömülü olduğunu savundu.'),
  ('"Bilgi sosyolojisi" (Wissenssoziologie) terimini 1920\'lerde ilk kez kullanan Alman düşünür kimdir?', 'Max Scheler', ['Karl Mannheim', 'Georg Simmel', 'Ferdinand Tönnies'], 'Terimi Max Scheler ortaya attı; Karl Mannheim ise bilgi sosyolojisini sistemli bir araştırma alanı olarak geliştirerek yaygınlaştırdı.'),
  ('Philip Selznick\'in Tennessee Vadisi İdaresi üzerine çalışmasında, bir örgütün dış tehditleri etkisizleştirmek için yerel güç odaklarını kendi karar mekanizmalarına katmasına verdiği ad hangisidir?', 'Kooptasyon', ['Asimilasyon', 'Rasyonelleşme', 'Seçkinlerin dolaşımı'], 'Selznick, örgütün muhalif ya da güçlü yerel grupları yönetime katarak desteklerini kazandığını, ancak bunun karşılığında amaçlarından ödün verdiğini gösterdi.'),
  ('Rosabeth Moss Kanter\'in büyük bir şirket üzerine çalışmasında, bir grupta sayıca çok az olan kadınların bireyler olarak değil, kategorilerinin temsilcisi olarak görülmesine verdiği ad hangisidir?', 'Simge (token) konumu', ['Ana statü', 'Rol mesafesi', 'Statü tutarsızlığı durumu'], 'Kanter, grubun yüzde 15\'inden az olan azınlık üyelerinin göze batan, sürekli izlenen ve kalıp yargılarla değerlendirilen simgeler haline geldiğini gösterdi.'),
  ('İkinci Dünya Savaşı sırasında Samuel Stouffer ve arkadaşlarının Amerikan askerleri üzerine yaptığı araştırmalarda, terfi oranı yüksek birliklerdeki askerlerin terfi konusunda daha hoşnutsuz olması hangi kavramın doğuşuna yol açmıştır?', 'Göreli yoksunluk', ['Mutlak yoksulluk sınırı', 'Kolektif coşku', 'Kültürel sermaye'], 'Askerler kendi durumlarını nesnel ölçütlere değil, karşılaştırdıkları kişilere göre değerlendiriyordu. Herkesin terfi aldığı yerde terfi alamamak daha büyük hoşnutsuzluk yaratıyordu.'),
  ('Everett Hughes\'un, bir meslekte toplumca hoş görülmeyen ya da itibar kaybettiren ama yapılması gereken görevler için kullandığı kavram hangisidir?', 'Kirli iş', ['Duygusal emek', 'Gösterişçi boş zaman', 'İkinci vardiya'], 'Hughes\'a göre her meslekte kirli işler vardır; meslek grupları bu işleri kendi içinde alt statülere devrederek saygınlıklarını korumaya çalışır.'),
  ('Raymond Boudon\'un, bireylerin kendi açılarından akla yatkın kararlarının toplandığında kimsenin istemediği sonuçlar doğurmasına verdiği ad hangisidir?', 'Ters (sapkın) etkiler', ['Kolektif coşku', 'Açık işlevler', 'Kendini doğrulayan kehanet'], 'Boudon, örneğin herkesin daha iyi iş için daha uzun eğitim almasının diplomaların değerini düşürmesi gibi, bireysel akılcılığın toplu düzeyde beklenmedik sonuçlar ürettiğini gösterdi.'),
  ('Arjun Appadurai\'nin küresel kültürel akışları çözümlemek için önerdiği kavramlar arasında insanların göç ve turizmle dünyadaki hareketini anlatan boyut hangisidir?', 'Etnik görünümler (ethnoscapes)', ['Medya görünümleri (mediascapes)', 'Teknoloji görünümleri (technoscapes)', 'Finans görünümleri (financescapes)'], 'Appadurai küresel akışları etnik, medya, teknoloji, finans ve ideoloji görünümleri olarak beşe ayırır. İnsanların hareketi etnik görünümleri oluşturur.'),
  ('"Yaşayanlar her zaman ve giderek artan ölçüde ölüler tarafından yönetilir" sözüyle geçmiş kuşakların birikiminin toplum üzerindeki ağırlığını vurgulayan düşünür kimdir?', 'Auguste Comte', ['Karl Marx', 'Max Weber', 'Herbert Spencer'], 'Comte, insanlığın sürekliliği ve geçmiş kuşakların bilgi ve kurumlarının bugünü biçimlendirdiği düşüncesini bu sözle ifade etti.'),
  ('Pierre Bourdieu hakkında çekilen bir belgesel filme adını veren ve onun sosyolojiye bakışını yansıtan söz hangisidir?', 'Sosyoloji bir dövüş sporudur', ['Sosyoloji bilimlerin kraliçesidir', 'Sosyoloji toplumsal fiziktir', 'Sosyoloji tarafsız bir aynadır'], 'Bourdieu sosyolojinin egemenlik ilişkilerini açığa çıkararak insanlara kendilerini savunma olanağı veren bir mücadele aracı olduğunu düşünüyordu; belgeselin adı da bu yüzden "Sosyoloji Bir Dövüş Sporudur"dur.'),
  ('Macaristan\'da doğan, 1933\'te Nazilerin iktidara gelmesiyle Frankfurt\'tan ayrılıp Londra Ekonomi Okulu\'nda (LSE) ders veren bilgi sosyoloğu kimdir?', 'Karl Mannheim', ['Max Ferdinand Scheler', 'Georg Lukács', 'Alfred Schutz'], 'Mannheim Budapeşte\'de doğdu, Heidelberg ve Frankfurt\'ta çalıştı; 1933\'ten sonra İngiltere\'de LSE\'de ders verdi ve planlama ile eğitim üzerine yazdı.'),
  ('Rus devriminden sonra ülkesinden sürülen ve 1930\'da Harvard Üniversitesi\'nde sosyoloji bölümünü kuran sosyolog kimdir?', 'Pitirim Sorokin', ['Talcott Parsons', 'George Caspar Homans', 'Robert Merton'], 'Sorokin 1922\'de Sovyet Rusya\'dan sürüldü, ABD\'ye yerleşti ve Harvard sosyoloji bölümünün kurucu başkanı oldu. Parsons da bu bölümde onunla birlikte çalıştı.'),
  ('Erving Goffman hangi ülkede doğmuştur?', 'Kanada', ['İngiltere', 'Avusturya', 'Avustralya'], 'Goffman 1922\'de Kanada\'nın Alberta eyaletinde doğdu; eğitimini Toronto ve Chicago\'da tamamladı ve kariyerini ABD\'de sürdürdü.'),
  ('Emile Durkheim\'ın aile geçmişine ilişkin bilgilerden hangisi doğrudur?', 'Kuşaklardır haham yetiştiren Yahudi bir aileden gelmesi', ['Askerî geleneği olan soylu bir Prusya aristokrat ailesinden gelmesi', 'Katolik bir rahibin oğlu olması', 'Babasının bir sanayi patronu olması'], 'Durkheim Fransa\'nın Lorraine bölgesinde, kuşaklardır haham yetiştiren bir ailede doğdu; gençliğinde bu yolu bırakıp laik bir akademik kariyere yöneldi.'),
  ('İbn Haldun\'un yaşamıyla ilgili aşağıdaki bilgilerden hangisi doğrudur?', '1401\'de Şam kuşatması sırasında Timur\'la görüşmüş olması', ['Mukaddime\'yi Osmanlı sarayında yazmış olması', 'Endülüs\'te doğup yaşamı boyunca hiç Kuzey Afrika\'ya ya da Mısır\'a gitmemiş olması', 'Bağdat\'ta Nizamiye Medresesi\'nin kurucusu olması'], 'Tunus\'ta doğan İbn Haldun Kahire\'de kadılık yaptı; 1401\'de Şam\'ı kuşatan Timur\'la görüşmesini otobiyografisinde anlatmıştır.'),
  ('Niyazi Berkes\'in 1942\'de yayımlanan ve Türkiye\'de alan araştırmasına dayalı ilk köy çalışmalarından sayılan eseri hangisidir?', 'Bazı Ankara Köyleri Üzerine Bir Araştırma', ['Hasanoğlan Köyü', 'Ereğli: Ağır Sanayiden Önce', 'Kentleşme ve Gecekondu'], 'Berkes bu çalışmasında Ankara çevresindeki köylerin toplumsal yapısını doğrudan gözlem ve görüşmelerle inceledi. Toplumsal Yapı Araştırmaları Behice Boran\'a, Ereğli Mübeccel Kıray\'a aittir.'),
  ('Mübeccel Kıray\'ın İzmir\'deki iş yaşamı ile kentsel yerleşme düzeni arasındaki ilişkiyi incelediği eseri hangisidir?', 'Örgütleşemeyen Kent', ['Gecekondu', 'Modern Mahrem', 'Kentli Köylüler ve Göç'], 'Kıray, İzmir\'de ticaret ve sanayi işletmelerinin kentsel mekâna dağılımını ve kentin modern bir örgütlenmeye geçişteki güçlüklerini "Örgütleşemeyen Kent"te inceledi.'),
  ('Şerif Mardin\'in Osmanlı aydınlarının ve Jön Türklerin düşünce dünyasını inceleyen eserlerinden biri hangisidir?', 'Jön Türklerin Siyasi Fikirleri', ['Türkiye\'de Devlet ve Sınıflar', 'Düzenin Yabancılaşması', 'Türkiye\'de Çağdaşlaşma'], 'Mardin\'in "Jön Türklerin Siyasi Fikirleri 1895-1908" adlı eseri, II. Meşrutiyet öncesinde muhalif aydınların düşüncelerini ayrıntılı biçimde çözümler.'),
  ('Deniz Kandiyoti\'nin kadınların ataerkil sistemlerin içinde kendi güvenliklerini ve yaşam koşullarını korumak için geliştirdikleri stratejileri anlatmak için kullandığı kavram hangisidir?', 'Ataerkil pazarlık', ['Duygusal emek', 'Kesişimsellik', 'Hegemonik erkeklik'], 'Kandiyoti 1988 tarihli makalesinde, kadınların farklı ataerkil düzenlerde var olan kurallar içinde pazarlık ederek kendilerine alan açtıklarını gösterdi.'),
  ('Çağlar Keyder\'in Türkiye\'nin toplumsal ve ekonomik gelişimini bürokrasi, burjuvazi ve köylülük arasındaki ilişkiler üzerinden incelediği eseri hangisidir?', 'Türkiye\'de Devlet ve Sınıflar', ['Türkiye\'de Çağdaşlaşma', 'Jön Türklerin Siyasi Fikirleri', 'Kültür Değişmeleri'], 'Keyder bu eserinde Osmanlı\'nın son döneminden Cumhuriyet\'e kadar devlet seçkinlerinin ve sınıfların ilişkisini dünya ekonomisi bağlamında çözümledi.'),
  ('Sencer Divitçioğlu\'nun Osmanlı toplumunun yapısını Marx\'ın bir kavramıyla açıklamaya çalıştığı 1967 tarihli eserinin adında geçen kavram hangisidir?', 'Asya üretim tarzı', ['Feodal üretim tarzı', 'Köleci üretim tarzı', 'Kapitalist üretim tarzı'], 'Divitçioğlu "Asya Üretim Tarzı ve Osmanlı Toplumu" adlı eserinde Osmanlı\'nın Batı feodalizminden farklı olduğunu ve Asya tipi üretim tarzına yakın özellikler taşıdığını savundu.'),
  ('Şerif Mardin\'in Türkiye\'de dinin toplumsal işlevlerini ve ideolojiyle ilişkisini tartıştığı 1969 tarihli eseri hangisidir?', 'Din ve İdeoloji', ['Modern Mahrem', 'Kültür Değişmeleri', 'Toplumsal Değişme Kuramları ve Türkiye Gerçeği'], 'Mardin "Din ve İdeoloji"de dinin bir kimlik ve dünya görüşü kaynağı olarak modern ideolojilerle ilişkisini ele aldı.'),
  ('Durkheim\'ın "Ahlak Eğitimi" adlı derslerinde laik ahlakın temel öğeleri olarak saydığı üç unsurdan biri hangisidir?', 'Disiplin ruhu', ['Kader öğretisine bağlılık', 'Kişisel çıkar hesabı', 'Ataların ruhlarına tapınma'], 'Durkheim ahlakın öğelerini disiplin ruhu, toplumsal gruplara bağlılık ve iradenin özerkliği olarak sıraladı; okulun bu öğeleri dinsel temele dayanmadan kazandırabileceğini savundu.'),
  ('Weber\'in din sosyolojisinde, çevresindeki toplum tarafından dinsel ve törensel kurallarla ayrı tutulan ve belirli mesleklere yönelmek zorunda kalan topluluğu anlatmak için kullandığı kavram hangisidir?', 'Parya halk', ['Seçilmiş halk', 'Karizmatik topluluk', 'Kolektif bilinç'], 'Weber bu kavramı, kast düzeni dışında kalan ya da toplumun geri kalanından törensel olarak ayrılmış, kendi içine kapalı ve belirli ekonomik işlevlere sıkıştırılmış topluluklar için kullandı.'),
  ('Marx\'ın 1871 Paris Komünü\'nü işçi sınıfının yönetim deneyimi olarak değerlendirdiği eseri hangisidir?', 'Fransa\'da İç Savaş', ['Felsefenin Sefaleti', 'Fransa\'da Sınıf Mücadeleleri', 'Gotha Programının Eleştirisi'], 'Marx, Paris Komünü\'nün hemen ardından yazdığı "Fransa\'da İç Savaş"ta Komün\'ü işçi sınıfının devlet iktidarını ele alma girişimi olarak çözümledi. "Fransa\'da Sınıf Mücadeleleri" 1848-1850 olaylarını konu alır.'),
  ('Marx\'ın "Felsefenin Sefaleti" adlı eserinin adı, hangi düşünürün "Sefaletin Felsefesi" adlı kitabına yanıt olarak verilmiştir?', 'Pierre-Joseph Proudhon', ['Ludwig Feuerbach', 'Adam Smith', 'Auguste Comte ve Saint-Simon'], 'Marx, Proudhon\'un "Ekonomik Çelişkiler Sistemi ya da Sefaletin Felsefesi" adlı eserini eleştirmek için başlığı tersine çevirerek 1847\'de bu kitabı yazdı.'),
  ('Marx\'ın kavramlarına göre işçinin günlük çalışma süresini ücret değişmeden uzatarak elde edilen artı değere ne ad verilir?', 'Mutlak artı değer', ['Göreli artı değer oranı', 'Kullanım değeri', 'Değişim değeri'], 'Marx iş gününü uzatarak elde edilen artı değeri mutlak, verimliliği artırıp işçinin geçim araçlarını üretmek için gereken süreyi kısaltarak elde edileni ise göreli artı değer olarak ayırır.'),
  ('Marx\'a göre İngiltere\'de ortak tarım arazilerinin çitlenerek köylülerin topraklarından koparılması kapitalizmin doğuşunda hangi süreç içinde yer alır?', 'İlkel birikim', ['Meta fetişizmi', 'Sınıf bilinci', 'Kâr oranlarının düşme eğilimi'], 'Marx, köylülerin topraktan zorla ayrılıp yalnızca emek gücünü satabilen proleterlere dönüştürülmesini ve servetin bir elde toplanmasını kapitalizmin ön koşulu olan ilkel birikim olarak açıklar.'),
  ('Georg Simmel\'in sosyolojinin asıl konusu olarak gördüğü ve bireylerin karşılıklı etkileşimle bir araya gelip toplumsal biçimler oluşturması sürecine verdiği ad hangisidir?', 'Sosyasyon', ['Rasyonelleşme', 'Yabancılaşma', 'Bireyselleşme ve özerkleşme'], 'Simmel toplumu sabit bir varlık olarak değil, bireylerin sürekli etkileşimleriyle oluşan bir süreç olarak gördü ve bu süreci toplumsallaşma (sosyasyon) kavramıyla anlattı.'),
  ('Michael Mann\'in toplumsal iktidarın kaynaklarını çözümlerken kullandığı dörtlü modelde yer alan iktidar kaynakları hangileridir?', 'İdeolojik, ekonomik, askerî ve siyasal', ['Dinsel, ailevi, kültürel ve sanatsal', 'Bireysel, ruhsal, bedensel, zihinsel ve duygusal', 'Yerel, bölgesel, ulusal ve küresel'], 'Mann "Toplumsal İktidarın Kaynakları" adlı çok ciltli eserinde tarihi bu dört iktidar ağının etkileşimi üzerinden açıkladı.'),
  ('Lipset ve Rokkan\'ın Avrupa\'daki parti sistemlerini açıklarken kullandığı kavram, partilerin hangi toplumsal ayrışmalardan doğduğunu vurgular?', 'Merkez-çevre, kilise-devlet, kır-kent ve işçi-işveren ayrışmaları', ['Yalnızca dil ve lehçe ayrılıkları', 'Yalnızca kuşaklar arası farklar', 'Yalnızca bireysel parti liderlerinin kişilik çatışmaları ve rekabetleri'], 'Lipset ve Rokkan, ulus inşası ve sanayi devrimi sırasında ortaya çıkan dört temel bölünme hattının Avrupa parti sistemlerini kalıcı biçimde şekillendirdiğini öne sürdü.'),
  ('Marcuse\'nin liberal toplumlarda her görüşe eşit hoşgörü gösterilmesinin aslında var olan eşitsizlikleri koruduğunu ileri sürdüğü 1965 tarihli denemesinin adı hangisidir?', 'Baskıcı Hoşgörü', ['Tek Boyutlu İnsan', 'Akıl ve Devrim', 'Özgürlükten Kaçış'], 'Marcuse bu denemede, güç ilişkileri eşit değilken tarafsız hoşgörünün egemen görüşlerin üstünlüğünü pekiştirdiğini ve muhalif sesleri etkisizleştirdiğini savundu.'),
  ('Max Horkheimer\'ın araçsal aklın amaçları sorgulayan nesnel aklı bastırmasını eleştirdiği 1947 tarihli eseri hangisidir?', 'Akıl Tutulması', ['Saf Aklın Eleştirisi', 'Akıl ve Devrim', 'Aklın Yıkımı'], 'Horkheimer "Akıl Tutulması"nda aklın yalnızca verilen amaçlara en verimli aracı bulan bir hesap yetisine indirgendiğini ve böylece etik içeriğini yitirdiğini savundu.'),
  ('Manuel Castells\'in "Kimliğin Gücü" adlı eserindeki ayrıma göre, ağ toplumunda dışlanan grupların egemen kurumlara karşı kendilerini savunmak için kurduğu kimlik türü hangisidir?', 'Direniş kimliği', ['Meşrulaştırıcı kimlik', 'Proje kimliği', 'Tüketici kimliği'], 'Castells egemen kurumlarca üretilen meşrulaştırıcı kimlikleri, damgalanan grupların sığınağı olan direniş kimliklerini ve toplumu dönüştürmeyi amaçlayan proje kimliklerini ayırır.'),
  ('Randall Collins\'in "Etkileşim Ritüeli Zincirleri" kuramına göre başarılı bir yüz yüze etkileşimden bireylerin kazandığı ve sonraki etkileşimlere taşıdığı şey nedir?', 'Duygusal enerji', ['Artı değer', 'Ekonomik sermaye', 'Kamusal alan'], 'Collins, Durkheim ve Goffman\'dan yararlanarak ortak odaklanma ve paylaşılan duygu içeren etkileşimlerin bireylere duygusal enerji verdiğini ve onları benzer etkileşimlere yönelttiğini savundu.'),
  ('Anselm Strauss\'un hastaneler üzerine çalışmasında, örgütsel düzenin resmî kurallardan çok çalışanlar arasında sürekli yapılan anlaşmalarla sürdürüldüğünü anlatan kavramı hangisidir?', 'Müzakere edilmiş düzen', ['Bürokratik ritüelcilik eğilimi', 'Demir kafes', 'Total kurum'], 'Strauss, hekimler, hemşireler ve hastalar arasındaki gündelik pazarlıkların hastanenin işleyişini belirlediğini ve düzenin sürekli yeniden müzakere edildiğini gösterdi.'),
  ('Goffman\'ın "Damga" adlı eserinde, damgası görünür olmayan kişilerin bu özelliklerini gizleyerek "normal" biri gibi kabul görmeye çalışmasına verdiği ad hangisidir?', 'Geçme', ['Rol mesafesi', 'Sivil kayıtsızlık', 'Ekip performansı'], 'Goffman, damgalanabilir kişilerin bilgiyi denetleyerek ve ipuçlarını saklayarak damgalanmamış gibi geçmeye çalıştığını; bunun sürekli bir kaygı ve dikkat gerektirdiğini gösterdi.'),
  ('Goffman\'ın 1982\'de Amerikan Sosyoloji Derneği başkanlık konuşması için hazırladığı metinde yüz yüze etkileşimi kendine özgü bir inceleme alanı olarak adlandırdığı kavram hangisidir?', 'Etkileşim düzeni', ['Toplumsal sistem kuramı', 'Dünya sistemi', 'Kamusal alan'], 'Goffman "Etkileşim Düzeni" başlıklı konuşmasında yüz yüze etkileşimin makro yapılara indirgenemeyecek kendi kuralları ve düzeni olan bir alan olduğunu savundu.'),
  ('Kâtip Çelebi\'nin 1653 tarihli "Düstûrü\'l-Amel" adlı risalesinde devletin gelişimini açıklarken kullandığı benzetme hangisidir?', 'Devleti büyüme, duraklama ve gerileme evreleri geçiren insan ömrüne benzetmesi', ['Devleti hiç değişmeyen bir dağa benzetmesi', 'Devleti birbirinden bağımsız çalışan dişlilerden oluşan ve hiç bozulmayan mekanik bir saate benzetmesi', 'Devleti yalnızca bir ticaret şirketine benzetmesi'], 'Kâtip Çelebi, İbn Haldun\'un etkisiyle devletin de insan gibi büyüme, duraklama ve gerileme evrelerinden geçtiğini ileri sürmüş ve mali bunalıma çözümler önermiştir.'),
  ('Osmanlı tarihçisi Naima\'nın tarihinin girişinde devletin geçirdiği evreleri açıklarken izlediği düşünür kimdir?', 'İbn Haldun', ['Farabi', 'Nizamülmülk', 'Gazali'], 'Naima, İbn Haldun\'un devletin kuruluşundan çöküşüne uzanan evreler kuramını Osmanlı Devleti\'ne uyguladı; bu, Mukaddime\'nin Osmanlı düşüncesindeki etkisinin önemli örneklerindendir.'),
  ('Durkheim\'ın "Sosyolojik Yöntemin Kuralları"nda sosyoloji için en uygun karşılaştırma yöntemi olarak gördüğü yöntem hangisidir?', 'Eş zamanlı değişimler yöntemi', ['Laboratuvar deneyi', 'İçebakış yöntemi', 'Rastgele örneklemli ulusal anket'], 'Durkheim, deney yapılamayan sosyolojide iki olgunun birlikte değişip değişmediğini farklı toplumlar ve dönemler arasında karşılaştırmanın nedensel ilişkiyi göstermenin en iyi yolu olduğunu savundu.'),
  ('Henry Mayhew\'un 19. yüzyıl ortasında yayımladığı ve sokak satıcıları, çöpçüler ve gündelikçilerle yapılan görüşmelere dayanan eseri hangi kentin yoksullarını konu alır?', 'Londra', ['Paris', 'Manchester', 'Dublin'], 'Mayhew\'un "Londra Emeği ve Londra Yoksulları" adlı eseri, yoksul emekçilerin kendi anlatımlarına yer vermesiyle sosyal araştırmanın öncü örneklerinden biridir.'),
  ('Bir avukatın müvekkiliyle yalnızca davayla ilgili konularda ilişki kurması, onun özel yaşamıyla ilgilenmemesi Parsons\'ın örüntü değişkenlerinden hangisine örnektir?', 'Belirlilik', ['Yaygınlık', 'Özelcilik', 'Duygusallık'], 'Parsons\'a göre belirli (özgül) ilişkiler sınırlı bir amaçla kurulur; aile içi ilişkiler gibi yaygın ilişkiler ise yaşamın pek çok alanını kapsar.'),
  ('Michel Maffesoli\'nin günümüz toplumunda insanların ortak beğeniler, spor ya da müzik etrafında kurduğu, geçici ve duygusal bağlara dayanan topluluklar için kullandığı kavram hangisidir?', 'Yeni kabileler', ['Mekanik dayanışma', 'Statü grupları', 'Zorunlu eşgüdümlü birlikler'], 'Maffesoli "Kabileler Zamanı" adlı eserinde bireyciliğin yerini akışkan, duygusal ve estetik paylaşıma dayanan küçük toplulukların aldığını savundu.'),
  ('Bir sosyolog, tüketim alışkanlıklarını incelerken bir ailenin komşularından geri kalmamak için onların aldığı arabanın benzerini almasını Veblen\'in hangi kavramıyla açıklar?', 'Parasal öykünme', ['Eğitilmiş yetersizlik', 'Gösterişçi boş zaman', 'İşçilik içgüdüsü'], 'Veblen\'e göre insanlar saygınlık kazanmak için kendilerinden üst konumdakilerin tüketim düzeyine yetişmeye çalışır; bu parasal öykünme sürekli bir harcama yarışı yaratır.'),
  ('İskoç Aydınlanması\'nın önemli düşünürlerinden Adam Ferguson\'ın 1767 tarihli ve toplumların gelişimini karşılaştırmalı biçimde ele aldığı eseri hangisidir?', 'Sivil Toplumun Tarihi Üzerine Bir Deneme', ['Ulusların Zenginliğinin Doğası ve Nedenleri Üzerine Bir İnceleme', 'Toplum Sözleşmesi', 'Leviathan'], 'Ferguson bu eserinde toplumların vahşetten barbarlığa ve uygarlığa geçişini, iş bölümünün ve ticaretin toplumsal bağlar üzerindeki etkilerini tartışarak sosyolojinin öncüleri arasına girdi.'),
  ('1909\'da kurulan Alman Sosyoloji Derneği\'nin ilk başkanı olan sosyolog kimdir?', 'Ferdinand Tönnies', ['Karl Heinrich Marx', 'Auguste Comte', 'Talcott Parsons'], 'Alman Sosyoloji Derneği Tönnies, Simmel ve Weber gibi isimlerin katılımıyla kuruldu; Tönnies uzun yıllar derneğin başkanlığını yürüttü.'),
  ('Werner Sombart\'ın 1906\'da yayımladığı ve sosyoloji tarihinde ünlü olan sorusunu başlığında taşıyan eseri hangisidir?', 'ABD\'de Neden Sosyalizm Yok?', ['Kapitalizmin Ruhu Nedir?', 'Toplum Nasıl Mümkündür?', 'Sosyoloji Nedir ve Ne İşe Yarar?'], 'Sombart, Amerikan işçilerinin görece yüksek yaşam standardını ve toplumsal hareketlilik olanaklarını, Avrupa\'dakine benzer güçlü bir sosyalist hareketin doğmamasının nedenleri arasında saydı.'),
  ('Robert Nisbet\'in "Sosyolojik Gelenek" adlı eserinde klasik sosyolojinin temel "birim fikirleri" arasında saydığı kavramlardan biri hangisidir?', 'Topluluk', ['Piyasa dengesi', 'Nüfus yoğunluğu', 'Kültürel gecikme'], 'Nisbet sosyolojik geleneği topluluk, otorite, statü, kutsal ve yabancılaşma olmak üzere beş birim fikir etrafında, bunların karşıtlarıyla birlikte çözümledi.'),
  ('Raymond Aron\'un "Sosyolojik Düşüncenin Evreleri" adlı eserinde ele aldığı düşünürler arasında aşağıdakilerden hangisi yer alır?', 'Alexis de Tocqueville', ['Michel Foucault', 'Pierre Bourdieu', 'Anthony Giddens'], 'Aron bu eserinde Montesquieu, Comte, Marx, Tocqueville, Durkheim, Pareto ve Weber\'i inceledi; Tocqueville\'in sosyoloji tarihindeki yerinin yeniden tanınmasında etkili oldu.'),
  ('Lewis Coser\'in üyelerinden tam bağlılık bekleyen ve onların başka bağlılıklarını zayıflatmaya çalışan kurumlar için kullandığı kavram hangisidir?', 'Açgözlü kurumlar', ['Total kurumlar', 'Emniyet supabı kurumları', 'Gönüllü kurumlar'], 'Coser\'e göre açgözlü kurumlar, total kurumlardan farklı olarak fiziksel duvarlar yerine bağlılık ve sadakat taleplerine dayanır; bazı tarikatlar ve siyasi örgütler buna örnektir.'),
  ('Hartmut Rosa\'nın modern toplumların temel eğilimi olarak gördüğü ve teknik değişim, toplumsal değişim ve yaşam temposunun birlikte artmasını anlatan kavramı hangisidir?', 'Toplumsal hızlanma', ['Kültürel gecikme', 'Zaman-mekân uzaklaşması', 'Seçkinlerin dolaşımı'], 'Rosa\'ya göre modernlik, her şeyin giderek hızlanmasıyla nitelenir; bu hızlanma yabancılaşmaya yol açar ve Rosa buna karşı dünyayla anlamlı bir "rezonans" ilişkisi önerir.'),
  ('Nancy Fraser\'ın toplumsal adalet tartışmasında birbirine indirgenemeyen iki boyut olarak ele aldığı kavramlar hangileridir?', 'Yeniden dağıtım ve tanınma', ['Artı değer ve kâr', 'Mekanik ve organik dayanışma', 'Ön sahne ve kulis'], 'Fraser, adaletsizliğin hem ekonomik eşitsizlikten hem de kültürel değersizleştirmeden kaynaklanabileceğini; bu yüzden ikisinin birlikte ele alınması gerektiğini savundu.'),
];
